<?php
/**
 * Tracy — com_content / category / blog_item
 *
 * Starts from the T4 base blog_item.php. Same data, same LayoutHelper calls, same param guards.
 * What changes is the SHAPE: the base emits a flat `.item-content` with the intro image floated
 * outside it, which cannot be given a card ring without the image hanging off the corner. Here the
 * item is one <article class="tracy-postcard"> with an explicit media slot and body slot, so
 * design-spec.md §6's card — 18px radius (--radius-lg), 1px ring (--elev-ring), NO shadow — has a
 * single element to bind to and the image clips to the same corner.
 *
 * Deliberately NOT a whole-card <a>: editability-standards.md §5 says a whole-card link must then
 * restyle every child or the card renders all-blue. The title link + readmore avoid that trap
 * entirely, and keep the base's access/authentication branching intact.
 *
 * $this->itemVariant is set by blog.php ('lead' | 'intro') so the lead card can run wider.
 */

defined('_JEXEC') or die;

use Joomla\CMS\Factory;
use Joomla\CMS\Language\Associations;
use Joomla\CMS\Layout\LayoutHelper;
use Joomla\CMS\Router\Route;
use Joomla\CMS\Uri\Uri;
use T4\Helper\J3J4;

// Create a shortcut for params.
$params  = $this->item->params;
$canEdit = $this->item->params->get('access-edit');
$info    = $params->get('info_block_position', 0);

// Check if associations are implemented. If they are, define the parameter.
$assocParam = (Associations::isEnabled() && $params->get('show_associations'));

$timePublishDown = $this->item->publish_down != null ? strtotime($this->item->publish_down) : '';
$timePublishUp   = $this->item->publish_up   != null ? strtotime($this->item->publish_up)   : '';

$isUnpublished = J3J4::checkUnpublishedContent($this->item)
    || $timePublishUp > strtotime(Factory::getDate())
    || (($timePublishDown < strtotime(Factory::getDate())) && $this->item->publish_down != Factory::getDbo()->getNullDate());

// Todo Not that elegant would be nice to group the params
$useDefList = ($params->get('show_modify_date') || $params->get('show_publish_date') || $params->get('show_create_date')
    || $params->get('show_hits') || $params->get('show_category') || $params->get('show_parent_category') || $params->get('show_author') || $assocParam);

// Rendered ahead of the markup so an article with no intro image gets no empty media slot at all
// (an empty slot would still draw the card's inner hairline).
$media = LayoutHelper::render('joomla.content.intro_image', $this->item);

$variant = isset($this->itemVariant) && $this->itemVariant === 'lead' ? ' tracy-postcard--lead' : '';
?>
<article class="tracy-postcard<?php echo $variant; ?><?php echo $isUnpublished ? ' system-unpublished' : ''; ?>">
	<?php if (trim($media) !== '') : ?>
		<div class="tracy-postcard__media">
			<?php echo $media; ?>
		</div>
	<?php endif; ?>

	<div class="item-content tracy-postcard__body">
		<?php echo LayoutHelper::render('joomla.content.blog_style_default_item_title', $this->item); ?>

		<div class="article-aside tracy-postcard__meta">
			<?php if ($useDefList && ($info == 0 || $info == 2)) : ?>
				<?php echo LayoutHelper::render('joomla.content.info_block', array('item' => $this->item, 'params' => $params, 'position' => 'above')); ?>
			<?php endif; ?>

			<?php if ($canEdit || $params->get('show_print_icon') || $params->get('show_email_icon')) : ?>
				<?php echo LayoutHelper::render('joomla.content.icons', array('params' => $params, 'item' => $this->item, 'print' => false)); ?>
			<?php endif; ?>
		</div>

		<?php if ($info == 0 && $params->get('show_tags', 1) && !empty($this->item->tags->itemTags)) : ?>
			<div class="tracy-tags"><?php echo LayoutHelper::render('joomla.content.tags', $this->item->tags->itemTags); ?></div>
		<?php endif; ?>

		<?php if (!$params->get('show_intro')) : ?>
			<?php // Content is generated by content plugin event "onContentAfterTitle" ?>
			<?php echo $this->item->event->afterDisplayTitle; ?>
		<?php endif; ?>

		<?php // Content is generated by content plugin event "onContentBeforeDisplay" ?>
		<?php echo $this->item->event->beforeDisplayContent; ?>

		<div class="item-intro tracy-postcard__intro">
			<?php echo $this->item->introtext; ?>
		</div>

		<?php if ($useDefList && ($info == 1 || $info == 2)) : ?>
			<div class="tracy-postcard__meta">
				<?php echo LayoutHelper::render('joomla.content.info_block', array('item' => $this->item, 'params' => $params, 'position' => 'below')); ?>
			</div>
			<?php if ($params->get('show_tags', 1) && !empty($this->item->tags->itemTags)) : ?>
				<div class="tracy-tags"><?php echo LayoutHelper::render('joomla.content.tags', $this->item->tags->itemTags); ?></div>
			<?php endif; ?>
		<?php endif; ?>

		<?php if ($params->get('show_readmore') && $this->item->readmore) :
			if ($params->get('access-view')) :
				$link = Route::_(ContentHelperRoute::getArticleRoute($this->item->slug, $this->item->catid, $this->item->language));
			else :
				$menu   = Factory::getApplication()->getMenu();
				$active = $menu->getActive();
				$itemId = $active ? $active->id : 0;
				$link   = new Uri(Route::_('index.php?option=com_users&view=login&Itemid=' . $itemId, false));
				$link->setVar('return', base64_encode(ContentHelperRoute::getArticleRoute($this->item->slug, $this->item->catid, $this->item->language)));
			endif; ?>

			<div class="tracy-postcard__action">
				<?php echo LayoutHelper::render('joomla.content.readmore', array('item' => $this->item, 'params' => $params, 'link' => $link)); ?>
			</div>
		<?php endif; ?>
	</div>
</article>

<?php // Content is generated by content plugin event "onContentAfterDisplay" ?>
<?php echo $this->item->event->afterDisplayContent; ?>
